action_input.code:
import csv

# Read all atoms and find the 4th atom for each carcinogenic molecule
carcinogenic_molecules = set()
with open('doc/molecule.md', 'r') as f:
    content = f.read()

import re
lines = content.split('\n')
current_mol = None
for line in lines:
    mol_match = re.search(r'TR\d+', line)
    if mol_match:
        current_mol = mol_match.group(0)
    if current_mol:
        lower_line = line.lower()
        if 'carcinogenic' in lower_line:
            carcinogenic_molecules.add(current_mol)

print(f"Carcinogenic molecules: {len(carcinogenic_molecules)}")

# Read atom.csv and find 4th atom for each carcinogenic molecule
atom_data = {}
with open('csv/atom.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        mol_id = row['molecule_id']
        atom_num = int(row['atom_id'].split('_')[1])
        element = row['element']

        if mol_id not in atom_data:
            atom_data[mol_id] = {}
        atom_data[mol_id][atom_num] = element

# Get 4th atom element for each carcinogenic molecule
results = []
for mol in sorted(carcinogenic_molecules):
    if mol in atom_data and 4 in atom_data[mol]:
        results.append([mol, atom_data[mol][4]])
    else:
        print(f"Missing 4th atom for {mol}")

print(f"Results count: {len(results)}")
for r in results[:10]:
    print(r)

